        "ready to charge",
        "ready_to_charge",
        "awaiting start",
        "awaiting_start",
        "charging",
        "completed",
        "complete"
    ],
    disconnectedStates: [
        "car disconnected",
        "car_disconnected",
        "disconnected"
    ],
    uncertainStates: [
        "unknown",
        "unavailable"
    ],

    cars: {
        ellingo: {
            name: "ElLingo",

            // Primćr hurtig status fra Tesla Custom Integration
            tracker: "device_tracker.ellingo_location_tracker_2",
            chargeCablePrimary: "binary_sensor.ellingo_charger",
            chargingPrimary: "binary_sensor.ellingo_charging",

            // Fallback fra Tesla Fleet
            trackerFleet: "device_tracker.ellingo_location",
            chargeCableFallback: "binary_sensor.ellingo_charge_cable",
            chargingFleet: "sensor.ellingo_charging",

            // Kommandoer via Fleet
            commandChargeSwitch: "switch.ellingo_charge"
        },
        blue_flux: {
            name: "Blue Flux",

            // Primćr hurtig status fra Tesla Custom Integration
            tracker: "device_tracker.location_tracker",
            chargeCablePrimary: "binary_sensor.charger",
            chargingPrimary: "binary_sensor.charging",

            // Fallback fra Tesla Fleet
            trackerFleet: "device_tracker.blue_flux_location",
            chargeCableFallback: "binary_sensor.blue_flux_charge_cable",
            chargingFleet: "sensor.blue_flux_charging",

            // Blue Flux er ny, sĺ kommandoer skal via Fleet
            commandChargeSwitch: "switch.blue_flux_charge"
        }
    },

    zones: {
        home: {
            name: "Home / Anemonevej",
            matchStates: ["home"],
            chargers: ["garage", "hegn"],
            cars: ["ellingo", "blue_flux"]
        },
        "I.A. Mřllersvej": {
            name: "I.A. Mřllersvej",
            matchStates: ["I.A. Mřllersvej"],
            chargers: ["ia_moellersvej_1", "ia_moellersvej_2"],
            cars: ["ellingo", "blue_flux"]
        }
    },

    chargers: {
        garage: {
            enabled: true,
            name: "Easee Garage",
            switch: "switch.garage_is_enabled",
            defaultCar: "ellingo"
        },
        hegn: {
            enabled: true,
            name: "Easee Hegn",
            switch: "switch.hegn_is_enabled",
            defaultCar: "blue_flux"
        },
        ia_moellersvej_1: {
            enabled: false,
            name: "Easee I.A. Mřllersvej 1",
            switch: "switch.ia_moellersvej_1_is_enabled",
            defaultCar: null
        },
        ia_moellersvej_2: {
            enabled: false,
            name: "Easee I.A. Mřllersvej 2",
            switch: "switch.ia_moellersvej_2_is_enabled",
            defaultCar: null
        }
    }
};

function statusEntityFromSwitch(switchEntity) {
    return switchEntity.replace("switch.", "sensor.").replace("_is_enabled", "_status");
}

function overrideEntityFromSwitch(switchEntity) {
    return switchEntity.replace("switch.", "input_boolean.").replace("_is_enabled", "_manual_until_disconnect");
}

const entities = new Set();
entities.add(CONFIG.modeEntity);

for (const car of Object.values(CONFIG.cars)) {
    if (car.tracker) entities.add(car.tracker);
    if (car.trackerFleet) entities.add(car.trackerFleet);
    if (car.chargeCablePrimary) entities.add(car.chargeCablePrimary);
    if (car.chargeCableFallback) entities.add(car.chargeCableFallback);
    if (car.chargingPrimary) entities.add(car.chargingPrimary);
    if (car.chargingFleet) entities.add(car.chargingFleet);
}

for (const [key, charger] of Object.entries(CONFIG.chargers)) {
    if (!charger.enabled) continue;
    const status = charger.status || statusEntityFromSwitch(charger.switch);
    const override = charger.override || overrideEntityFromSwitch(charger.switch);
    if (charger.switch) entities.add(charger.switch);
    if (status) entities.add(status);
    if (override) entities.add(override);
}

const requests = Array.from(entities).filter(Boolean).map(entity_id => ({
    entity_id,
    _ev_poll: true,
    _ev_poll_ts: Date.now()
}));

const watchdog = {
    _ev_watchdog: true,
    payload: Date.now()
};

return [requests, watchdog];

const CONFIG = {
    specVersion: "1.0",
    defaultBrainMode: "Log only",              // Disabled | Log only | Production
    modeEntity: "input_select.ev_charger_brain_mode",
