            switch: "switch.hegn_is_enabled",
            defaultCar: "blue_flux"
        },
        ia_moellersvej_1: {
            enabled: false,
            name: "Easee I.A. Mřllersvej 1",
            switch: "switch.ia_moellersvej_1_is_enabled",
            defaultCar: null
        },
        ia_moellersvej_2: {
            enabled: false,
            name: "Easee I.A. Mřllersvej 2",
            switch: "switch.ia_moellersvej_2_is_enabled",
            defaultCar: null
        }
    }
};

function statusEntityFromSwitch(switchEntity) {
    return switchEntity.replace("switch.", "sensor.").replace("_is_enabled", "_status");
}

function overrideEntityFromSwitch(switchEntity) {
    return switchEntity.replace("switch.", "input_boolean.").replace("_is_enabled", "_manual_until_disconnect");
}

function nowMs() { return Date.now(); }
function norm(v) { return String(v ?? "").trim(); }
function normLower(v) { return norm(v).toLowerCase(); }
function isOn(v) { return ["on", "true", "connected", "yes"].includes(normLower(v)); }
function isOff(v) { return ["off", "false", "disconnected", "no"].includes(normLower(v)); }
function csv(v) {
    let s = String(v ?? "");
    s = s.replace(/\r?\n/g, " ").replace(/;/g, ",");
    return s;
}
function ts(ms) {
    const d = new Date(ms || Date.now());
    const pad = n => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}
function chargerStatusClass(state) {
    const raw = normLower(state);
    const canonical = raw.replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();
    const connected = CONFIG.connectedLikeStates.map(x => normLower(x).replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim());
    const disconnected = CONFIG.disconnectedStates.map(x => normLower(x).replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim());
    const uncertain = CONFIG.uncertainStates.map(x => normLower(x).replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim());
    if (connected.includes(canonical)) return "connected_like";
    if (disconnected.includes(canonical)) return "disconnected";
    if (uncertain.includes(canonical)) return "uncertain";
    return "other";
}
function getBrainMode(states) {
    const s = states[CONFIG.modeEntity]?.state;
    const v = norm(s || CONFIG.defaultBrainMode);
    if (["Disabled", "Log only", "Production"].includes(v)) return v;
    const l = v.toLowerCase();
    if (l === "disabled") return "Disabled";
    if (l === "production") return "Production";
    return "Log only";
}
function enabledChargers() {
    return Object.fromEntries(Object.entries(CONFIG.chargers).filter(([_, c]) => c.enabled));
}
function statusEntity(chargerKey) {
    const c = CONFIG.chargers[chargerKey];
    return c.status || statusEntityFromSwitch(c.switch);
}
function overrideEntity(chargerKey) {
    const c = CONFIG.chargers[chargerKey];
    return c.override || overrideEntityFromSwitch(c.switch);
}
function chargerZone(chargerKey) {
    for (const [zoneKey, z] of Object.entries(CONFIG.zones)) {
        if ((z.chargers || []).includes(chargerKey)) return zoneKey;
    }
    return null;
}
function carTrackerStates(carKey, states) {
    const car = CONFIG.cars[carKey];
    if (!car) return [];
    return [car.tracker, car.trackerFleet]
        .filter(Boolean)
        .map(e => ({ entity: e, state: norm(states[e]?.state || "unknown") }));
}
function stateMatchesZone(state, zoneKey) {
    const zone = CONFIG.zones[zoneKey];
    if (!zone) return false;
    return (zone.matchStates || [zoneKey]).includes(state) || state === zoneKey;
}
function carZoneMatches(carKey, zoneKey, states) {
    return carTrackerStates(carKey, states).some(t => stateMatchesZone(t.state, zoneKey));
}
function carCurrentZone(carKey, states) {
    const trackerStates = carTrackerStates(carKey, states);
    for (const t of trackerStates) {
        for (const [zoneKey, z] of Object.entries(CONFIG.zones)) {
            if ((z.matchStates || [zoneKey]).includes(t.state) || t.state === zoneKey) return zoneKey;
        }
    }
    const primary = trackerStates[0]?.state;
    return primary || "unknown";
}
function carCableEntities(carKey) {
    const car = CONFIG.cars[carKey];
    if (!car) return [];
    return [
        { source: "primary", entity: car.chargeCablePrimary },
        { source: "fallback", entity: car.chargeCableFallback }
    ].filter(x => x.entity);
}
function carCableState(carKey, states) {
    const parts = carCableEntities(carKey).map(x => `${x.source}:${norm(states[x.entity]?.state || "unknown")}`);
    return parts.join("|") || "unknown";
}
function carCableIsOn(carKey, states) {
    return carCableEntities(carKey).some(x => isOn(states[x.entity]?.state));
}
function carCableRecentlyOn(carKey, states, t) {
    return carCableEntities(carKey).some(x => {
        const lastOn = states[x.entity]?.lastOnTs || 0;
        return lastOn && (t - lastOn) <= CONFIG.cableEventWindowSeconds * 1000;
    });
}
function chargerSwitchState(chargerKey, states) {
    const c = CONFIG.chargers[chargerKey];
    return norm(states[c.switch]?.state || "unknown");
}
function chargerStatusState(chargerKey, states) {
    return norm(states[statusEntity(chargerKey)]?.state || "unknown");
}
function assignedCarsExcept(sessions, chargerKey) {
    const used = new Set();
    for (const [ck, s] of Object.entries(sessions)) {
        if (ck === chargerKey) continue;
        if (s && s.assignedCar && ["auto_assigned", "manual_until_disconnect"].includes(s.mode)) {
            used.add(s.assignedCar);
        }
    }
    return used;
}
function entityRole(entity) {
    if (entity === CONFIG.modeEntity) return { kind: "mode" };
    for (const [carKey, car] of Object.entries(CONFIG.cars)) {
        if (entity === car.tracker) return { kind: "car_tracker", carKey, source: "primary" };
        if (entity === car.trackerFleet) return { kind: "car_tracker", carKey, source: "fleet" };
        if (entity === car.chargeCablePrimary) return { kind: "car_cable", carKey, source: "primary" };
        if (entity === car.chargeCableFallback) return { kind: "car_cable", carKey, source: "fallback" };
        if (entity === car.chargingPrimary) return { kind: "car_charging", carKey, source: "primary" };
        if (entity === car.chargingFleet) return { kind: "car_charging", carKey, source: "fleet" };
    }
    for (const [chargerKey, charger] of Object.entries(enabledChargers())) {
        if (entity === charger.switch) return { kind: "charger_switch", chargerKey };
        if (entity === statusEntity(chargerKey)) return { kind: "charger_status", chargerKey };
        if (entity === overrideEntity(chargerKey)) return { kind: "charger_override", chargerKey };
    }
    return { kind: "unknown" };
}

let states = flow.get("ev_brain_v10_states") || {};
let sessions = flow.get("ev_brain_v10_sessions") || {};
let meta = flow.get("ev_brain_v10_meta") || { startedAt: nowMs(), headerWritten: false };

for (const [chargerKey, c] of Object.entries(enabledChargers())) {
    if (!sessions[chargerKey]) {
        sessions[chargerKey] = {
            mode: "disconnected",
            assignedCar: null,
            lastAssignedCar: null,
            lastConnectedTs: null,
            lastDisconnectedTs: null,
            pendingSinceTs: null,
            pendingExpiredLogged: false,
            lastAction: null
        };
    }
}

const outServices = [];
const outLogs = [];
const outNotify = [];
const outDebug = [];

function appendLog(fields) {
    if (!meta.headerWritten) {
        outLogs.push({ payload: "timestamp;spec_version;brain_mode;zone;charger_key;charger_name;car_key;car_name;event;charger_status;charger_switch;car_zone;car_charge_cable;session_mode;action;reason;details" });
        meta.headerWritten = true;
    }
    const charger = fields.chargerKey ? CONFIG.chargers[fields.chargerKey] : null;
    const car = fields.carKey ? CONFIG.cars[fields.carKey] : null;
    const zone = fields.zoneKey || (fields.chargerKey ? chargerZone(fields.chargerKey) : "");
    const line = [
        ts(),
        CONFIG.specVersion,
        getBrainMode(states),
        zone || "",
        fields.chargerKey || "",
        charger?.name || "",
        fields.carKey || "",
        car?.name || "",
        fields.event || "",
        fields.chargerStatus ?? (fields.chargerKey ? chargerStatusState(fields.chargerKey, states) : ""),
        fields.chargerSwitch ?? (fields.chargerKey ? chargerSwitchState(fields.chargerKey, states) : ""),
        fields.carZone ?? (fields.carKey ? carCurrentZone(fields.carKey, states) : ""),
        fields.carCable ?? (fields.carKey ? carCableState(fields.carKey, states) : ""),
        fields.sessionMode || (fields.chargerKey ? sessions[fields.chargerKey]?.mode : ""),
        fields.action || "none",
        fields.reason || "",
        fields.details || ""
    ].map(csv).join(";");
    outLogs.push({ payload: line });
}
function notify(title, message) {
    const mode = getBrainMode(states);
    if (mode === "Production" || CONFIG.sendNotificationsInLogOnly) {
        outNotify.push({ title, payload: message });
    }
}
function planService(haAction, entityId, fields) {
    const mode = getBrainMode(states);
    let logAction = haAction;
    if (mode === "Log only") logAction = "WOULD_" + haAction;
    if (mode === "Disabled") logAction = "SKIP_" + haAction;
    appendLog({ ...fields, action: logAction });
    if (mode === "Production") {
        outServices.push({ ha_action: haAction, entity_id: entityId, brain_mode: mode, payload: { entity_id: entityId } });
    }
}
function turnOnCharger(chargerKey, reason, carKey, event) {
    const sw = CONFIG.chargers[chargerKey].switch;
    const current = chargerSwitchState(chargerKey, states);
    sessions[chargerKey].lastAction = "turn_on";
    if (isOn(current)) {
        appendLog({ chargerKey, carKey, event, action: "already_on", reason, sessionMode: sessions[chargerKey].mode });
    } else {
        planService("switch.turn_on", sw, { chargerKey, carKey, event, reason, sessionMode: sessions[chargerKey].mode });
    }
}
function turnOffCharger(chargerKey, reason, carKey, event) {
    const sw = CONFIG.chargers[chargerKey].switch;
    const current = chargerSwitchState(chargerKey, states);
    sessions[chargerKey].lastAction = "turn_off";
    if (isOff(current)) {
        appendLog({ chargerKey, carKey, event, action: "already_off", reason, sessionMode: sessions[chargerKey].mode });
    } else {
        planService("switch.turn_off", sw, { chargerKey, carKey, event, reason, sessionMode: sessions[chargerKey].mode });
    }
}
function clearOverride(chargerKey, reason, event) {
    const ov = overrideEntity(chargerKey);
    const current = norm(states[ov]?.state || "unknown");
    if (isOn(current)) {
        planService("input_boolean.turn_off", ov, { chargerKey, event, reason, sessionMode: sessions[chargerKey].mode });
    }
}
function assignAndTurnOn(chargerKey, carKey, reason, event) {
    sessions[chargerKey].mode = "auto_assigned";
    sessions[chargerKey].assignedCar = carKey;
    sessions[chargerKey].lastAssignedCar = carKey;
    sessions[chargerKey].pendingSinceTs = null;
    sessions[chargerKey].pendingExpiredLogged = false;
    appendLog({ chargerKey, carKey, event: event || "assigned", action: "assign", reason, sessionMode: sessions[chargerKey].mode });
    turnOnCharger(chargerKey, reason, carKey, event || "turn_on");
}
function validCandidatesForCharger(chargerKey) {
    const zoneKey = chargerZone(chargerKey);
    const zone = CONFIG.zones[zoneKey];
    const used = assignedCarsExcept(sessions, chargerKey);
    if (!zone) return { zoneKey, candidates: [], cableCandidates: [] };
    const candidates = (zone.cars || [])
        .filter(carKey => CONFIG.cars[carKey])
        .filter(carKey => !used.has(carKey))
        .filter(carKey => carZoneMatches(carKey, zoneKey, states));
    const t = nowMs();
    const cableCandidates = candidates.filter(carKey => {
        return carCableIsOn(carKey, states) || carCableRecentlyOn(carKey, states, t);
    });
    return { zoneKey, candidates, cableCandidates };
}
function tryMatch(chargerKey, reasonBase) {
    const { zoneKey, candidates, cableCandidates } = validCandidatesForCharger(chargerKey);
    const c = CONFIG.chargers[chargerKey];
    if (cableCandidates.length === 1) {
        assignAndTurnOn(chargerKey, cableCandidates[0], reasonBase || "charge_cable_and_charger_same_zone", "connected_like");
        return true;
    }
    if (cableCandidates.length > 1) {
        if (c.defaultCar && cableCandidates.includes(c.defaultCar)) {
            assignAndTurnOn(chargerKey, c.defaultCar, "default_tiebreaker_same_zone", "connected_like");
            return true;
        }
        sessions[chargerKey].mode = "ambiguous";
        appendLog({ chargerKey, event: "ambiguous", action: "none", reason: "multiple_valid_cable_candidates_no_default", details: cableCandidates.join(","), sessionMode: "ambiguous" });
        notify("EV Charger Brain: Ambiguous", `${c.name}: flere valide biler i ${zoneKey}: ${cableCandidates.join(", ")}`);
        return false;
    }
    const wasPending = sessions[chargerKey].mode === "pending_match";
    sessions[chargerKey].mode = "pending_match";
    if (!sessions[chargerKey].pendingSinceTs) sessions[chargerKey].pendingSinceTs = nowMs();
    sessions[chargerKey].pendingExpiredLogged = false;
    if (!wasPending) {
        appendLog({ chargerKey, event: "pending_match", action: "none", reason: "no_known_car_with_charge_cable_in_zone", details: `cars_in_zone=${candidates.join(",")}`, sessionMode: "pending_match" });
    }
    return false;
}
function carStillValidForReplug(carKey, zoneKey) {
    if (!CONFIG.cars[carKey]) return false;
    const currentZone = carCurrentZone(carKey, states);
    if (currentZone === zoneKey) return true;
    const trackerState = normLower(states[CONFIG.cars[carKey].tracker]?.state);
    if (["unknown", "unavailable"].includes(trackerState)) return true;
    return false;
}
function handleConnectedLike(chargerKey, reason) {
    const t = nowMs();
    const s = sessions[chargerKey];
    const zoneKey = chargerZone(chargerKey);
    s.lastConnectedTs = t;
    const ov = overrideEntity(chargerKey);
    if (isOn(states[ov]?.state)) {
        s.mode = "manual_until_disconnect";
        appendLog({ chargerKey, event: "connected_like", action: "manual_mode", reason: "manual_override_active", sessionMode: s.mode });
        turnOnCharger(chargerKey, "manual_override_active", s.assignedCar, "override_connected_like");
        return;
    }
    if (s.lastAssignedCar && s.lastDisconnectedTs && (t - s.lastDisconnectedTs) <= CONFIG.replugWindowSeconds * 1000 && carStillValidForReplug(s.lastAssignedCar, zoneKey)) {
        assignAndTurnOn(chargerKey, s.lastAssignedCar, "replug_same_session", "reconnect");
        return;
    }
    tryMatch(chargerKey, reason || "connected_like");
}
function handleDisconnected(chargerKey) {
    const s = sessions[chargerKey];
    const previousCar = s.assignedCar || s.lastAssignedCar || null;
    if (s.assignedCar) s.lastAssignedCar = s.assignedCar;
    s.assignedCar = null;
    s.mode = "disconnected";
    s.lastDisconnectedTs = nowMs();
    s.pendingSinceTs = null;
    s.pendingExpiredLogged = false;
    appendLog({ chargerKey, carKey: previousCar, event: "disconnected", action: "clear_assignment", reason: "charger_disconnected", sessionMode: s.mode });
    turnOffCharger(chargerKey, "charger_disconnected", previousCar, "disconnect");
    clearOverride(chargerKey, "charger_disconnected", "override_cleared_by_disconnect");
}
function handleCarCableOn(carKey) {
    const zoneKey = carCurrentZone(carKey, states);
    for (const chargerKey of Object.keys(enabledChargers())) {
        const s = sessions[chargerKey];
        if (chargerZone(chargerKey) !== zoneKey) continue;
        if (s.mode === "pending_match" || chargerStatusClass(chargerStatusState(chargerKey, states)) === "connected_like") {
            tryMatch(chargerKey, "charge_cable_update_after_pending");
        }
    }
}
function handleOverride(chargerKey, newState) {
    const s = sessions[chargerKey];
    if (isOn(newState)) {
        s.mode = "manual_until_disconnect";
        appendLog({ chargerKey, event: "override_on", action: "manual_mode", reason: "helper_on", sessionMode: s.mode });
        turnOnCharger(chargerKey, "manual_override_on", s.assignedCar, "override_on");
        notify("EV Charger Brain: Override", `${CONFIG.chargers[chargerKey].name}: manual until disconnect er slĺet til.`);
    } else if (isOff(newState) && s.mode === "manual_until_disconnect") {
        s.mode = chargerStatusClass(chargerStatusState(chargerKey, states)) === "connected_like" ? "pending_match" : "disconnected";
        appendLog({ chargerKey, event: "override_off", action: "none", reason: "helper_off", sessionMode: s.mode });
    }
}
function watchdog() {
    for (const chargerKey of Object.keys(enabledChargers())) {
        const s = sessions[chargerKey];
        const cls = chargerStatusClass(chargerStatusState(chargerKey, states));
        if (cls === "disconnected") {
            if (!isOff(chargerSwitchState(chargerKey, states))) {
                s.mode = "disconnected";
                turnOffCharger(chargerKey, "watchdog_disconnected_switch_on", s.assignedCar, "watchdog");
            }
            if (isOn(states[overrideEntity(chargerKey)]?.state)) {
                clearOverride(chargerKey, "watchdog_disconnected_override_on", "watchdog");
            }
        }
        if (cls === "connected_like") {
            if (["disconnected", "pending_match"].includes(s.mode)) {
                tryMatch(chargerKey, "watchdog_re_evaluate_connected_like");
            }
            if (s.mode === "pending_match" && s.pendingSinceTs && (nowMs() - s.pendingSinceTs) > CONFIG.pendingCableTimeoutSeconds * 1000 && !s.pendingExpiredLogged) {
                s.mode = "connected_unassigned";
                s.pendingExpiredLogged = true;
                appendLog({ chargerKey, event: "connected_unassigned", action: "none", reason: "pending_match_timeout", details: `timeout_seconds=${CONFIG.pendingCableTimeoutSeconds}`, sessionMode: s.mode });
                notify("EV Charger Brain: Unassigned", `${CONFIG.chargers[chargerKey].name}: bil/lader kunne ikke matches sikkert.`);
            }
        }
    }
}

// Process incoming state poll
if (msg._ev_poll) {
    const entity = msg.entity_id || msg.topic || msg.data?.entity_id;
    const newState = norm(msg.payload ?? msg.data?.state);
    if (entity) {
        const prev = states[entity]?.state;
        const changed = prev !== undefined && prev !== newState;
        const role = entityRole(entity);
        const entry = states[entity] || {};
        entry.prevState = prev;
        entry.state = newState;
        entry.updatedTs = nowMs();
        if (changed) entry.changedTs = nowMs();
        if (role.kind === "car_cable" && isOn(newState) && (changed || !entry.lastOnTs)) entry.lastOnTs = nowMs();
        if (role.kind === "car_cable" && isOff(newState) && changed) entry.lastOffTs = nowMs();
        states[entity] = entry;

        if (changed) {
            if (role.kind === "charger_status") {
                const cls = chargerStatusClass(newState);
                if (cls === "connected_like") handleConnectedLike(role.chargerKey, "charger_status_changed_connected_like");
                else if (cls === "disconnected") handleDisconnected(role.chargerKey);
                else if (cls === "uncertain") appendLog({ chargerKey: role.chargerKey, event: "charger_status_uncertain", action: "none", reason: newState, sessionMode: sessions[role.chargerKey]?.mode });
                else appendLog({ chargerKey: role.chargerKey, event: "charger_status_other", action: "none", reason: newState, sessionMode: sessions[role.chargerKey]?.mode });
            }
            if (role.kind === "car_cable") {
                appendLog({ carKey: role.carKey, event: "car_charge_cable_changed", action: "none", reason: `${role.source || "unknown"}:${newState}` });
                if (isOn(newState)) handleCarCableOn(role.carKey);
            }
            if (role.kind === "car_charging") {
                appendLog({ carKey: role.carKey, event: "car_charging_changed", action: "none", reason: `${role.source || "unknown"}:${newState}` });
            }
            if (role.kind === "car_tracker") {
                const assigned = Object.entries(sessions).find(([_, s]) => s.assignedCar === role.carKey);
                if (assigned) {
                    const [chargerKey] = assigned;
                    const cls = chargerStatusClass(chargerStatusState(chargerKey, states));
                    if (cls === "connected_like") appendLog({ chargerKey, carKey: role.carKey, event: "car_state_ignored", action: "none", reason: `tracker_changed_to_${newState}_but_charger_connected_like` });
                } else {
                    appendLog({ carKey: role.carKey, event: "car_tracker_changed", action: "none", reason: newState });
                }
            }
            if (role.kind === "charger_override") handleOverride(role.chargerKey, newState);
            if (role.kind === "mode") appendLog({ event: "brain_mode_changed", action: "none", reason: newState });
        }
    }
}

if (msg._ev_watchdog) {
    watchdog();
}

flow.set("ev_brain_v10_states", states);
flow.set("ev_brain_v10_sessions", sessions);
flow.set("ev_brain_v10_meta", meta);

const mode = getBrainMode(states);
node.status({ fill: mode === "Production" ? "green" : (mode === "Disabled" ? "grey" : "yellow"), shape: "dot", text: `v${CONFIG.specVersion} ${mode}` });
outDebug.push({ payload: { mode, sessions, updated: ts() } });

return [outServices, outLogs, outNotify, outDebug];
